 const icon=(n,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.file}"/></svg>`;
 const btn=(label,action,n='',cls='',extra='')=>`<button class="btn ${cls}" data-action="${action}" ${extra}>${n?icon(n):''}${label}</button>`;
 const textbtn=(label,action,extra='')=>`<button class="text-btn" data-action="${action}" ${extra}>${label}${icon('arrow')}</button>`;
